def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    prev_valid = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                prev_valid.append((float(bid), opp))

    if not alive_opps:
        if hp <= 3 or no_water_days >= 2:
            return float(min(budget, 45.0))
        return float(min(budget, 12.0))

    prev_bids.sort()
    highest_prev = prev_bids[-1] if prev_bids else 0.0
    second_prev = prev_bids[-2] if len(prev_bids) >= 2 else highest_prev

    emergency = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1
    ample_supply = supply >= 21
    tight_supply = supply <= 17

    rich_aggressive = 0
    for bid_val, opp in prev_valid:
        if bid_val >= 100 and opp.get('budget', 0) >= 150:
            rich_aggressive += 1

    if emergency:
        target = max(78.0, min(118.0, second_prev + 3.0))
        if tight_supply:
            target += 8.0
        return float(min(budget, target))

    if pressured:
        if ample_supply:
            target = max(48.0, min(88.0, second_prev * 0.72 + 4.0))
        else:
            target = max(36.0, min(72.0, second_prev * 0.58 + 2.0))
        return float(min(budget, target))

    if rich_aggressive >= 2 and not ample_supply:
        return float(min(budget, 8.0))

    if highest_prev >= 120:
        if ample_supply:
            target = 34.0
        else:
            target = 10.0
    elif highest_prev >= 100:
        target = 18.0 if not ample_supply else 30.0
    else:
        target = max(20.0, min(55.0, highest_prev + 2.5))

    if day >= 8 and hp >= 7 and budget < 120:
        target *= 0.75

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o is not None and o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        # If no opponents, conserve budget
        return float(min(budget, DAILY_SALARY * 0.4))

    # Use only yesterday's previous_trace to react
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Base target bid: aim slightly below typical survivors to avoid overpaying
    # but still compete against Cindy/Eric/David range.
    if yesterday_bids:
        sorted_bids = sorted(yesterday_bids)
        # Median-like estimate without numpy
        m = sorted_bids[len(sorted_bids)//2]
        # If there was a very high bid, pressure likely exists; bid closer to it.
        top = sorted_bids[-1]

        # Detect if someone died yesterday => indicates too much competition; we can be careful.
        died_flag = False
        for o in alive_opps:
            prev = o.get('previous_trace', {}) or {}
            if prev and prev.get('hp_after', None) == 0:
                died_flag = True
                break

        # Compute aggressiveness based on our hp/no_water_days
        urgency = 0
        if hp <= 2:
            urgency = 2
        elif hp <= 4:
            urgency = 1
        if no_water_days >= 2:
            urgency += 1

        # Supply factor: if supply is near minimum, competition is higher; bid more.
        supply_factor = 0.0
        if supply <= float(MIN_SUPPLY):
            supply_factor = 0.12
        elif supply >= float(MAX_SUPPLY):
            supply_factor = -0.05
        else:
            # interpolate roughly
            supply_factor = 0.12 - (supply - float(MIN_SUPPLY)) * (0.17 / (float(MAX_SUPPLY) - float(MIN_SUPPLY)))

        # Target: median minus a small discount unless urgency forces escalation.
        discount = 0.08
        if died_flag:
            discount = 0.12  # be slightly more conservative when someone already died

        target = m * (1.0 - discount) + (top - m) * 0.15

        # Urgency adjustment
        if urgency == 0:
            target *= (1.0 + supply_factor)
        elif urgency == 1:
            target *= (1.0 + supply_factor + 0.07)
        else:
            target = max(target, m * 0.98)  # close to median
            target *= (1.0 + supply_factor + 0.12)

    else:
        # No trace bids available; default moderate
        target = DAILY_SALARY * 0.55
        if hp <= 4 or no_water_days >= 2:
            target = DAILY_SALARY * 0.75

    # Ensure we don't bid more than budget
    bid = float(min(budget, max(0.0, target)))

    # If our budget is very low, still try to survive: bid proportionally to urgency
    if budget < DAILY_SALARY * 0.6:
        if hp <= 2 or no_water_days >= 2:
            bid = float(min(budget, DAILY_SALARY * 0.9))
        else:
            bid = float(min(budget, DAILY_SALARY * 0.55))

    # Final cap: avoid extreme overbids late in day 10 (episode_days=10 typically)
    # day is within 1..10; be slightly more conservative as day increases.
    if day >= 9:
        bid *= 0.92

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}
    num_alive = len(alive_opponents) + 1

    # own urgency: low hp or already without water
    if hp <= 2 or no_water_days >= 1:
        own_urgency = 'high'
    elif hp <= 5:
        own_urgency = 'medium'
    else:
        own_urgency = 'low'

    # analyze opponents
    desperate_opponents = 0
    prev_bids = []
    for o in alive_opponents.values():
        if o['hp'] <= 2:
            desperate_opponents += 1
        prev = o.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            prev_bids.append(prev['bid'])

    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.7

    # estimate competition intensity
    supply_per_player = supply / num_alive
    scarcity = supply_per_player < WATER_REQ

    # decide target bid
    if own_urgency == 'high':
        # must win water at almost any cost
        if desperate_opponents > 0:
            # outbid maximum possible desperation bid (approx salary)
            target = min(budget, DAILY_SALARY * 0.95)
        else:
            # still need water, but can be moderate
            target = min(budget, max(DAILY_SALARY * 0.8, avg_prev_bid + 2))
    elif own_urgency == 'medium':
        # can afford to let some water go if price high
        if scarcity or desperate_opponents >= 2:
            target = min(budget, max(DAILY_SALARY * 0.6, avg_prev_bid + 1))
        else:
            target = min(budget, DAILY_SALARY * 0.5)
    else:  # low urgency
        # not desperate, save money
        if desperate_opponents >= 1:
            # let them fight, bid low
            target = min(budget, DAILY_SALARY * 0.4)
        else:
            target = min(budget, DAILY_SALARY * 0.3)

    # ensure positive bid and budget constraint
    bid = max(0.1, target)
    return min(budget, bid)
